import json,pathlib,html,subprocess,sys
base=pathlib.Path(__file__).resolve().parent.parent/'dist'
subprocess.run([sys.executable, str(base.parent/'scripts/seasonal-art.py')], check=True)
d=json.loads((base/'content.json').read_text());credits=json.loads((base/'assets/credits.json').read_text())
esc=html.escape
sources={e['sourceUrl']:e['sourceLabel'] for k in ['sites','people','news'] for e in d[k]}
sources['https://nataliehaynes.com/about/']='Natalie Haynes · author biography'
sources['https://www.ucas.com/explore/subjects/classics']='UCAS · Classics and career routes'
sources['https://archaeology.org/feed/']='Archaeology magazine (Archaeological Institute of America) · discovery feed'
sources['https://www.thecollector.com/news/']='TheCollector · News & Discoveries'
sources['https://greekreporter.com/tag/archaeology/']='Greek Reporter · archaeology'
sources.update({event['sourceUrl']:event['sourceLabel'] for event in d.get('events',[])})
body='''<!doctype html><html lang="en-GB"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sources and credits | Classics display</title><link rel="stylesheet" href="credits.css"><main><a href="./">← Return to the display</a><h1>Sources & credits</h1><p>Landmark and graduate connections were checked on 2 November 2026. Recent discovery stories retain their original publication dates. A daily source check scans Archaeology magazine, TheCollector’s News &amp; Discoveries and Greek Reporter’s archaeology coverage for short, attributed notices; older stories are labelled as archive material.</p><h2>Editorial sources</h2><ul>'''
for url,label in sources.items():body+=f'<li><a href="{esc(url)}">{esc(label)}</a></li>'
body+='</ul><h2>Photographs</h2><p>Images are bundled locally and shown using responsive crops. Landmark photographs are shown in full; portrait and welcome photographs may be cropped to fit. No colour filters are applied. Image licences apply independently of the website code.</p>'
for c in credits:
 body+=f'<article><h3>{esc(c["file"])}</h3><p>{esc(c["title"])}<br>{esc(c.get("adaptation", "Displayed with a responsive crop."))}<br>Creator: {esc(c["artist"])}<br>Licence: <a href="{esc(c["licenceUrl"] or c["page"])}">{esc(c["licence"])}</a> · <a href="{esc(c["page"])}">Original and licence details</a></p></article>'
body+='''<h2>Gulliver & typography</h2><p>Gulliver adapts the user-owned, code-drawn Eastbourne gull from the supplied personal dashboard, adding an explorer’s hat, scarf and suitcase. This is an original character asset, not the College logo. No personal P or C symbols are used.</p><p>Nimbus Roman and Nimbus Sans are bundled unmodified from the existing personal homepage. <a href="assets/fonts/FONT_LICENSE.txt">Font copyright, licence and source details</a>.</p><h2>Content notes</h2><p>Pompeii news screens use an identified location photograph of the forum, not a photograph of the reported discovery. Automatic feed notices use an original archaeology illustration and a short source extract. Charlotte Higgins uses an original name graphic rather than a portrait. These graphics were drawn in SVG for this display. Career connections are editorial examples of transferable skills, not promises of admission or employment. Gulliver’s remarks are fictional.</p><p>When replacing an image, keep the creator, original link, licence and any required adaptation notice with the file. Update this page and assets/credits.json.</p></main></html>'''
body=body.replace('<h2>Content notes</h2>', '<h2>Seasonal graphics</h2><p>The seasonal treatments were revised on 7 November 2026. All eighteen seasonal treatments are original code-drawn animations with matching static SVG fallbacks and calendar previews. They use flat, stylised motifs such as colour strands, poppies, awareness ribbons, page shapes, olive branches, waves and flames. The earlier AI-generated botanical poppy PNG is retained among the bundled assets but is no longer selected by the display. The supplied photographs were visual references. <a href="calendar.html">Annual events calendar, display windows and sources</a>.</p><h2>Content notes</h2>')
(base/'credits.html').write_text(body)

calendar='''<!doctype html><html lang="en-GB"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Annual events calendar | Classics display</title><link rel="stylesheet" href="credits.css"><main><a href="./">← Return to the display</a><h1>Annual events calendar</h1><p>Seasonal borders change automatically during the inclusive display windows below, using the Europe/London date. Modern observances use artwork without an overlaid caption. Ancient festival names are part of their colour-matched artwork, with a brief explanation above the main content. All eighteen treatments use moving graphics; the previews below show their static fallbacks. The notes here provide the background and sources.</p><p>Easter follows the Western Gregorian calculation. Remembrance ends on the Sunday of the week containing 11 November and takes precedence during its window. Other overlapping graphics alternate between screens and loops.</p><p>Display windows are editorial choices. Roman dates are conventional month-and-day anniversaries in the modern calendar. Ancient practice varied. Organiser-set campaign weeks and UK World Book Day use confirmed dates for the years listed. Later dates need checking when announced. Fixed annual dates and Easter continue automatically.</p><p>Calendar sources were checked on 7 November 2026. <a href="credits.html">Full sources and image credits</a>.</p>'''
for event in d.get('events',[]):
 calendar+=f'''<article class="calendar-event"><img src="{esc(event['image'])}" alt="{esc(event['imageAlt'])}" width="160" height="105"><div><p>{esc(event['kind'])}</p><h2>{esc(event['title'])}</h2><p><strong>Display window</strong> {esc(event['displayWindow'])}<br><strong>Observance</strong> {esc(event['observance'])}</p><p>{esc(event['body'])}</p><p><a href="{esc(event['sourceUrl'])}">{esc(event['sourceLabel'])}</a></p></div></article>'''
 calendar+=f'<img class="calendar-border" src="{esc('assets/seasons/'+event['id']+'-named.svg' if event.get('designName') else event['borderImage'])}" alt="Decorative border for {esc(event["title"])}">' if event.get('borderImage') else ''
calendar+='</main></html>'
(base/'calendar.html').write_text(calendar)
